WITH events AS (SELECT * FROM (SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Entered' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='E')) WHERE object_id LIKE 'MED:%' UNION ALL SELECT * FROM (SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Reviewed' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='R')) WHERE object_id LIKE 'MED:%' UNION ALL SELECT * FROM (SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Cancelled' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='C')) WHERE object_id LIKE 'MED:%' UNION ALL SELECT * FROM (SELECT 'EMAR:'||e.emar_id event_id,'MED:'||o.order_id object_id,'Medication Administered' activity,e.charttime timestamp FROM emar e JOIN pharmacy p ON p.pharmacy_id=e.pharmacy_id JOIN medication_order o ON o.order_id=p.order_id WHERE e.charttime IS NOT NULL AND (e.event_txt='Administered')) WHERE object_id LIKE 'MED:%' UNION ALL SELECT * FROM (SELECT 'MED:'||order_id||':stop' event_id,'MED:'||order_id object_id,'Medication Stopped' activity,stopped_at timestamp FROM medication_order WHERE stopped_at IS NOT NULL AND (1=1)) WHERE object_id LIKE 'MED:%' UNION ALL SELECT * FROM (SELECT 'PHARM:'||pharmacy_id||':dispense' event_id,'MED:'||order_id object_id,'Medication Dispensed' activity,dispensed_at timestamp FROM pharmacy WHERE dispensed_at IS NOT NULL AND (1=1)) WHERE object_id LIKE 'MED:%' UNION ALL SELECT * FROM (SELECT 'EMAR:'||e.emar_id event_id,'MED:'||o.order_id object_id,'Medication Not Given' activity,e.charttime timestamp FROM emar e JOIN pharmacy p ON p.pharmacy_id=e.pharmacy_id JOIN medication_order o ON o.order_id=p.order_id WHERE e.charttime IS NOT NULL AND (e.event_txt='Not Given')) WHERE object_id LIKE 'MED:%'), orders AS (SELECT 'MED:'||m.order_id object_id,m.hadm_id,a.subject_id FROM medication_order m JOIN admissions a USING(hadm_id)) SELECT e.event_id,'P:'||o.subject_id case_id,e.activity,e.timestamp FROM events e JOIN orders o ON o.object_id=e.object_id WHERE o.subject_id IS NOT NULL ORDER BY case_id,timestamp,event_id;
